std::string decoded_text = "";
std::shared_ptr<Node> current = root;
int bits_read = 0;

while (bits_read < encoded_length) {
    char byte;
    if (!infile.get(byte)) break;

    for (int i = 7; i >= 0 && bits_read < encoded_length; --i) {
        bool bit = (byte >> i) & 1;

        if (bit) {
            current = current->right;
        } else {
            current = current->left;
        }

        if (!current->left && !current->right) {
            decoded_text += current->data;
            current = root;
        }
        bits_read++;
    }
}

return decoded_text;
// END_CODE

